const X = window.GYX;

/* ==== 📸 TA的相册 ==== */
try { new Function('X', 'applyMacros', "/* 📸 TA 的相册：把聊天里 TA 发过的照片、画给你的涂鸦、寄来的明信片按月份收成一本相册（原来散在聊天记录里）；TA 还会主动拍一张生活碎片发给你——发图走原来的「角色发图」，不另造 */\nif (window.__gyxAlbum) return; window.__gyxAlbum = 1;\nX.feat('gyxAlbum', { n: '📸 TA 的相册', desc: 'TA 发的照片自动收进相册，TA 还会拍生活碎片' });\nconst S = X.store('album');\nlet D = { snaps: [], cfg: { per: 25 } };   // snaps: {id, cid, at, desc, cap, src, emo, bg}\nconst BGS = [['#ffd6a5', '#fdffb6'], ['#caffbf', '#9bf6ff'], ['#a0c4ff', '#bdb2ff'], ['#ffc6ff', '#fffffc'], ['#f4a261', '#e9c46a'], ['#264653', '#2a9d8f'], ['#1d3557', '#457b9d']];\nconst IDEA = [['傍晚的天', '🌇☁️'], ['路过的一只猫', '🐈🌿'], ['今天的咖啡', '☕📖'], ['下雨的窗', '🌧️🪟'], ['晚饭', '🍜🥢'], ['加班的桌子', '💻🌙'], ['路边的花', '🌼🌱'], ['地铁上的风景', '🚇🌆'], ['街角的灯', '💡🌃'], ['今天的月亮', '🌙✨']];\nasync function snap(c) {\n    let j;\n    if (X.bailu()) { const [d, e] = X.pick(IDEA); j = { desc: d, cap: X.cards(['相册', '聊天'], c, 1)[0] || d, emo: e }; }\n    else j = X.json(await X.ask(`${X.who(c)}\\n最近的聊天：\\n${X.recent(c, 10)}\\n\\n你今天随手拍了一张生活里的照片，想放进给她看的相册。拍的是什么（符合你的身份和今天的生活，具体一点）？配一句话。\\n只输出 JSON：{\"desc\":\"照片内容（15 字以内，用来生成图片）\",\"cap\":\"配的一句话\",\"emo\":\"两个最能代表画面的 emoji\"}`)) || { desc: X.pick(IDEA)[0], cap: '今天也想分享给你', emo: '📷✨' };\n    let src = '', core = false;\n    // 原项目有「角色发图」（js/42）就走它：照片卡片、生图/图库/搜图、形象词、开关和频率都跟原来一样，不另造一套\n    try { if (window.gyPhotoFromReply && (!window.gyPhotoModeOf || window.gyPhotoModeOf(c.id) !== 'off')) { X.say(c, `📸 ${j.cap || ''}`); core = !!(await window.gyPhotoFromReply(c.id, c.id, j.desc, false)); } } catch (e) {}\n    if (!core) { try { if (window.gyPhotoGet) { const g = await window.gyPhotoGet(c.id, j.desc, false); src = g && g.src || ''; } } catch (e) {} }\n    const it = { id: 'sn' + Date.now(), cid: String(c.id), at: Date.now(), desc: String(j.desc || ''), cap: String(j.cap || ''), src, emo: String(j.emo || '📷'), bg: X.pick(BGS), core };\n    D.snaps.unshift(it); await S.set('d', D);\n    if (!core) X.say(c, `📸 ${it.cap}`, src ? { mediaUrl: src } : {});\n    return it;\n}\nwindow.gyxAlbumSnap = id => snap(X.char(id) || X.cur());\n// 相册里的所有东西：聊天里 TA 发的图 + 生活碎片 + 涂鸦 + 明信片\nasync function items(cid) {\n    const out = [];\n    const H = (typeof globalChats !== 'undefined' && globalChats[cid]) || [];\n    H.forEach(m => { if (String(m.sender) !== String(cid)) return; if (m.type === 'photo' && m.photo) out.push({ k: 'photo', at: m.timestamp, src: m.photo.src || '', cap: m.photo.desc || '', emo: '📷' }); else if (m.mediaUrl && !/^\\[涂鸦\\]/.test(m.text || '') && !m.gyx) out.push({ k: 'chat', at: m.timestamp, src: m.mediaUrl, cap: X.plain(m.text).slice(0, 40) }); });\n    D.snaps.filter(s => s.cid === cid && !s.core).forEach(s => out.push({ k: 'snap', at: s.at, src: s.src, cap: s.cap, desc: s.desc, emo: s.emo, bg: s.bg }));\n    try { const G = await X.store('doodle').get('g', []); G.filter(g => g.cid === cid && g.by !== 'me').forEach(g => out.push({ k: 'doodle', at: g.at, src: g.src, cap: '画给你的：' + (g.title || '') })); } catch (e) {}\n    try { const P = window.gyxPostData && window.gyxPostData(); (P && P.list || []).filter(p => p.cid === cid && p.arrived).forEach(p => out.push({ k: 'post', at: p.at, src: '', cap: '明信片 · ' + p.place, emo: '🏞️', bg: ['#a0c4ff', '#caffbf'] })); } catch (e) {}\n    return out.sort((a, b) => b.at - a.at);\n}\nwindow.gyxAlbumOpen = async function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), L = await items(cid);\n    const byM = {}; L.forEach(x => { const d = new Date(x.at), k = d.getFullYear() + ' 年 ' + (d.getMonth() + 1) + ' 月'; (byM[k] = byM[k] || []).push(x); });\n    window.__gyxAlbumL = L;\n    X.panel('gyxAlOv', `📸 ${X.esc(X.name(c))} 的相册`, `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxAlbumOpen')}<span class=\"gyx-tip\">${L.length} 张</span><button class=\"gyx-btn lite\" style=\"margin-left:auto\" onclick=\"this.disabled=true;this.textContent='TA 在拍……';gyxAlbumSnap('${cid}').then(()=>gyxAlbumOpen('${cid}'))\">让 TA 拍一张</button></div>\n        ${Object.entries(byM).map(([m, xs]) => `<div class=\"al-m\">${m}</div><div class=\"al-grid\">${xs.map(x => `<div class=\"al-it\" onclick=\"gyxAlbumView(${L.indexOf(x)})\">${x.src ? `<img src=\"${X.esc(x.src)}\" loading=\"lazy\">` : `<div class=\"al-ph\" style=\"background:linear-gradient(135deg,${(x.bg || BGS[0]).join(',')})\"><span>${X.esc(x.emo || '📷')}</span><em>${X.esc(x.desc || '')}</em></div>`}<i>${{ photo: '📷', chat: '💬', snap: '✨', doodle: '🎨', post: '🏞️' }[x.k]}</i></div>`).join('')}</div>`).join('') || '<div class=\"gyx-tip\">相册还是空的。TA 发照片、画画、寄明信片都会自动收进来。</div>'}\n        <div class=\"gyx-row gyx-tip\">默认模式的 TA 每天有 <input class=\"gyx-who\" type=\"number\" min=\"0\" max=\"100\" value=\"${D.cfg.per}\" style=\"width:60px\" onchange=\"gyxAlbumCfg(+this.value)\">% 的可能拍一张生活碎片；自主模式的 TA 自己决定。</div>`);\n};\nwindow.gyxAlbumView = function (i) {\n    const x = (window.__gyxAlbumL || [])[i]; if (!x) return;\n    const ov = document.createElement('div'); ov.className = 'al-view'; ov.onclick = () => ov.remove();\n    ov.innerHTML = `<div class=\"al-pol\">${x.src ? `<img src=\"${X.esc(x.src)}\">` : `<div class=\"al-ph big\" style=\"background:linear-gradient(135deg,${(x.bg || BGS[0]).join(',')})\"><span>${X.esc(x.emo || '📷')}</span><em>${X.esc(x.desc || '')}</em></div>`}<p class=\"gyx-hand\">${X.esc(x.cap || '')}</p><small>${new Date(x.at).toLocaleString()}</small></div>`;\n    document.body.appendChild(ov);\n};\nwindow.gyxAlbumCfg = v => { D.cfg.per = v; S.set('d', D); };\nwindow.gyxAlbumData = () => D;\nasync function tick() { if (!X.on('gyxAlbum')) return; const k = X.day(); if (D.last === k) return; const h = new Date().getHours(); if (h < 10 || h > 21) return; D.last = k; await S.set('d', D); for (const c of X.chars()) { if (X.auto(c)) continue; if (Math.random() * 100 < (+D.cfg.per || 0)) { await snap(c); break; } } }\nX.action({ key: 'gyx_album', label: '拍一张生活碎片放进给她的相册', hint: '今天看到的好看的东西', need: c => !D.snaps.some(s => s.cid === String(c.id) && X.day(new Date(s.at)) === X.day()), run: async c => (await snap(c)) ? '拍了一张生活碎片给你' : null }, 'gyxAlbum');\nX.today(() => ({ title: '📸 相册', rows: D.snaps.filter(s => X.day(new Date(s.at)) === X.day()).map(s => ({ t: X.name(X.char(s.cid)), x: '拍了：' + X.esc(s.cap || s.desc), go: `gyxAlbumOpen('${s.cid}')` })) }), 'gyxAlbum');\nX.widget('gyxAlbum', { n: 'TA 的相册', sizes: ['s', 'm'], tap: () => window.gyxAlbumOpen(), r: () => { const s = D.snaps[0]; if (!s) return '<div class=\"gw-al\"><b>📸</b><em>TA 的相册</em></div>'; return `<div class=\"gw-al\">${s.src ? `<img src=\"${X.esc(s.src)}\">` : `<div class=\"al-ph\" style=\"background:linear-gradient(135deg,${s.bg.join(',')})\"><span>${X.esc(s.emo)}</span></div>`}<em>${X.esc(s.cap)}</em></div>`; } }, 'gyxAlbum');\nX.css('gyxAlCss', `.al-m{font-size:13px;color:#8e8e93;margin:14px 0 6px}.al-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(100px,1fr));gap:6px}.al-it{position:relative;aspect-ratio:1;border-radius:10px;overflow:hidden;cursor:pointer;background:#f2f2f4}.al-it img{width:100%;height:100%;object-fit:cover;display:block}.al-it>i{position:absolute;right:4px;bottom:4px;font-style:normal;font-size:12px;background:rgba(255,255,255,.8);border-radius:6px;padding:0 3px}\n.al-ph{width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.al-ph span{font-size:34px}.al-ph em{font-style:normal;font-size:11px;color:rgba(0,0,0,.55);padding:0 6px}.al-ph.big{aspect-ratio:1}.al-ph.big span{font-size:80px}.al-ph.big em{font-size:14px}\n.al-view{position:fixed;inset:0;z-index:100006;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;padding:20px}.al-pol{background:#fff;padding:14px 14px 18px;width:min(420px,90vw);box-shadow:0 20px 50px rgba(0,0,0,.4);transform:rotate(-1.5deg);animation:giPol .6s both}.al-pol img{width:100%;display:block}.al-pol p{font-size:20px;margin:12px 0 4px;color:#3b3024}.al-pol small{color:#aaa}\n@keyframes giPol{from{opacity:0;transform:translateY(-40px) rotate(6deg)}to{opacity:1;transform:rotate(-1.5deg)}}\n.gw-al{height:100%;display:flex;flex-direction:column;gap:4px}.gw-al img,.gw-al .al-ph{flex:1;min-height:0;width:100%;object-fit:cover;border-radius:12px}.gw-al em{font-style:normal;font-size:11.5px;color:var(--pm-sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.gw-al b{font-size:34px;font-weight:normal;text-align:center}`);\nX.mini({ id: 'gyxAlbum', icon: '📸', title: 'TA 的相册', desc: 'TA 发的照片、涂鸦、明信片都收在这；TA 还会拍生活碎片', onOpen: () => window.gyxAlbumOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.snaps = D.snaps || []; D.cfg = Object.assign({ per: 25 }, D.cfg || {}); setTimeout(tick, 25000); setInterval(tick, 30 * 60000); })();\nX.memArr({ k: 'gyxAlbum', ico: '📸', n: 'TA 分享的生活碎片', d: '拍下来给你看的', arr: () => D.snaps, text: x => x.cap || x.desc, field: 'cap', meta: x => new Date(x.at).toLocaleString(), save: () => S.set('d', D) }, 'gyxAlbum');\n\n//# sourceURL=gyx-plugin/TA的相册.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 📸 TA的相册 出错：', e); }
/* ==== 🎨 表情包工坊 ==== */
try { new Function('X', 'applyMacros', "/* 🎨 表情包工坊：拿 TA 的立绘、头像、你们的合照，或者你自己的图，配上字，做成表情包——一键存进「表情包」库，聊天里 TA 和你都能发。TA 也会自己做两张来跟你斗图 */\nif (window.__gyxMeme) return; window.__gyxMeme = 1;\nX.feat('gyxMeme', { n: '🎨 表情包工坊', desc: '用 TA 的立绘 / 合照配字做表情包，存进表情包库，TA 也会做来斗图' });\nconst S = X.store('meme');\nlet D = { list: [] };   // [{id, cid, src(合成后的图), text, by:'me'|'ta', at, emo(表情包库里的 id)}]\nconst PHR = ['在吗', '想你了', '哼', '不理你了', '抱抱', '你好可爱', '我错了', '收到', '好耶', '晚安', '早安', '就这？', '委屈', '亲亲', '呜呜呜', '盯——', '在忙', '饿了', '快夸我', '你说得对', '我先睡了', '再说一遍', '摸摸头', '不许走', '冲鸭', '笑死', '救命', '乖', '好的老婆', '拿捏了'];\nconst ST = { img: '', top: '', bottom: '想你了', size: 44, color: '#ffffff', stroke: '#222222', font: 'sans', shape: 'sq', bg: '#ffffff' };\nconst FONTS = { sans: '\"PingFang SC\",\"Microsoft YaHei\",sans-serif', hand: '\"Ma Shan Zheng\",\"Long Cang\",\"KaiTi\",cursive', bold: '\"Noto Sans SC\",\"Heiti SC\",\"SimHei\",sans-serif' };\nconst imgOf = c => { try { return (window.gyxPetImgOf && window.gyxPetImgOf(c)) || c.avatarImg || ''; } catch (e) { return (c && c.avatarImg) || ''; } };\nfunction sources(c) {\n    const L = []; const a = imgOf(c); if (a) L.push(['立绘', a]); if (c.avatarImg && c.avatarImg !== a) L.push(['头像', c.avatarImg]);\n    try { (window.gyxDuoData ? window.gyxDuoData().pics : []).filter(x => x.cid === String(c.id)).slice(0, 6).forEach((x, i) => L.push(['合照' + (i + 1), x.src])); } catch (e) {}\n    try { (window.gyGallery ? window.gyGallery.seenBy(String(c.id)) : []).slice(-6).forEach((x, i) => L.push(['图库' + (i + 1), x.src])); } catch (e) {}\n    return L;\n}\nconst load = src => new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = src; });\nasync function render(o) {\n    const W = 320, H = o.shape === 'wide' ? 240 : 320, cv = document.createElement('canvas'); cv.width = W; cv.height = H; const g = cv.getContext('2d');\n    g.fillStyle = o.bg || '#fff'; g.fillRect(0, 0, W, H);\n    if (o.img) { try { const im = await load(o.img); const k = Math.min(W / im.width, (H - (o.bottom ? 40 : 0) - (o.top ? 40 : 0)) / im.height) * 1; const w = im.width * k, h = im.height * k; g.drawImage(im, (W - w) / 2, (o.top ? 40 : 0) + ((H - (o.bottom ? 40 : 0) - (o.top ? 40 : 0)) - h) / 2, w, h); } catch (e) {} }\n    const txt = (t, y) => { if (!t) return; let fs = +o.size || 44; g.font = `900 ${fs}px ${FONTS[o.font] || FONTS.sans}`; while (g.measureText(t).width > W - 16 && fs > 14) { fs -= 2; g.font = `900 ${fs}px ${FONTS[o.font] || FONTS.sans}`; } g.textAlign = 'center'; g.textBaseline = 'middle'; g.lineJoin = 'round'; g.lineWidth = Math.max(3, fs / 7); g.strokeStyle = o.stroke; g.strokeText(t, W / 2, y); g.fillStyle = o.color; g.fillText(t, W / 2, y); };\n    txt(o.top, 28); txt(o.bottom, H - 28);\n    try { return cv.toDataURL('image/png'); } catch (e) { if (o.img) { X.toast('🎨 这张图是网络图片，浏览器不让合成', '先存到本地再上传就行'); return render(Object.assign({}, o, { img: '' })); } return ''; }\n}\nasync function save(c, src, text, by) {\n    const it = { id: 'mm' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4), cid: String(c.id), src, text, by, at: Date.now() };\n    try { if (typeof globalEmoticons !== 'undefined') { const id = 'emo_' + Date.now() + '_' + Math.floor(Math.random() * 1e4); globalEmoticons.push({ id, url: src, desc: (by === 'ta' ? X.name(c) + '做的：' : '') + text }); it.emo = id; saveAllData(); } } catch (e) {}\n    D.list.unshift(it); await S.set('d', D); return it;\n}\nfunction sendMsg(c, it, who) { try { const sid = String(c.id); globalChats[sid] = globalChats[sid] || []; globalChats[sid].push({ sender: who === 'me' ? 'me' : c.id, text: '', mediaUrl: it.src, timestamp: Date.now(), readBy: [], gyx: 1 }); saveAllData(); if (typeof renderChatMessages === 'function' && String(currentChatSessionId) === sid) renderChatMessages(); } catch (e) {} }\nasync function paint() { const b = document.getElementById('gyxMmPrev'); if (!b) return; b.src = await render(ST); }\nwindow.gyxMemeSet = (k, v) => { ST[k] = v; paint(); if (k === 'img') document.querySelectorAll('.mm-src img').forEach(e => e.classList.toggle('on', e.getAttribute('data-s') === String(v).slice(0, 60))); };\nwindow.gyxMemeUp = inp => { const f = inp.files && inp.files[0]; if (!f) return; const fr = new FileReader(); fr.onload = () => window.gyxMemeSet('img', fr.result); fr.readAsDataURL(f); };\nwindow.gyxMemeSave = async (cid, send) => { const c = X.char(cid); if (!c) return null; const src = await render(ST); const it = await save(c, src, [ST.top, ST.bottom].filter(Boolean).join(' '), 'me'); if (send) { sendMsg(c, it, 'me'); X.toast('🎨 发出去了', ''); } else X.toast('🎨 存进表情包库了', '聊天里点表情就能找到'); window.gyxMemeOpen(cid, 'mine'); return it; };\nasync function taMake(c, why) {\n    let t = X.bailu() ? null : X.plain(await X.ask(`${X.who(c)}\\n你要用自己的照片做一张表情包${why ? '（' + why + '）' : '来跟她斗图'}，配一句很短的字（2~8 个字，有梗、像你会说的）。\\n最近的聊天：\\n${X.recent(c, 8)}\\n只输出那句字。`) || '');\n    t = (t || X.pick(X.cards(['表情', '字词'], c, 2).filter(x => x.length <= 8).concat(PHR))).replace(/[\"「」]/g, '').slice(0, 10);\n    const src = await render(Object.assign({}, ST, { img: imgOf(c), top: '', bottom: t, color: X.pick(['#ffffff', '#ffe066', '#ffb3c7']), font: X.pick(['sans', 'hand', 'bold']) }));\n    return save(c, src, t, 'ta');\n}\nwindow.gyxMemeTa = async cid => { const c = X.char(cid) || X.cur(); const it = await taMake(c, ''); sendMsg(c, it, 'ta'); window.gyxMemeOpen(c.id, 'mine'); return it; };\nwindow.gyxMemeSend = id => { const it = D.list.find(x => x.id === id), c = it && X.char(it.cid); if (c) { sendMsg(c, it, 'me'); X.toast('🎨 发出去了', ''); } };\nwindow.gyxMemeDel = async id => { const it = D.list.find(x => x.id === id); D.list = D.list.filter(x => x.id !== id); try { if (it && it.emo && typeof globalEmoticons !== 'undefined') { const i = globalEmoticons.findIndex(e => e.id === it.emo); if (i >= 0) globalEmoticons.splice(i, 1); saveAllData(); } } catch (e) {} await S.set('d', D); window.gyxMemeOpen(it && it.cid, 'mine'); };\nwindow.gyxMemeData = () => D;\nwindow.gyxMemeOpen = function (who, tab) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), src = sources(c); if (!ST.img && src[0]) ST.img = src[0][1];\n    if (tab === 'mine') { X.panel('gyxMmOv', '🎨 表情包工坊', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxMemeOpen')}<span class=\"gyx-chip\" onclick=\"gyxMemeOpen('${cid}')\">‹ 去做新的</span><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxMemeTa('${cid}')\">让 TA 做一张来斗图</button></div><div class=\"mm-grid\">${D.list.filter(x => x.cid === cid).map(x => `<div><img src=\"${x.src}\"><em>${x.by === 'ta' ? 'TA 做的' : '我做的'}</em><span><a onclick=\"gyxMemeSend('${x.id}')\">发送</a><a onclick=\"gyxMemeDel('${x.id}')\">删</a></span></div>`).join('') || '<div class=\"gyx-tip\">还没做过</div>'}</div>`); return; }\n    X.panel('gyxMmOv', '🎨 表情包工坊', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxMemeOpen')}<span class=\"gyx-chip\" onclick=\"gyxMemeOpen('${cid}','mine')\">我们的表情包（${D.list.filter(x => x.cid === cid).length}）</span></div>\n        <div class=\"mm-wrap\"><img id=\"gyxMmPrev\" class=\"mm-prev\"><div class=\"mm-ctl\">\n        <div class=\"mm-src\">${src.map(([n, s]) => `<img src=\"${s}\" title=\"${n}\" data-s=\"${X.esc(s.slice(0, 60))}\" class=\"${ST.img === s ? 'on' : ''}\" onclick=\"gyxMemeSet('img',this.src)\">`).join('')}<label class=\"mm-up\">＋<input type=\"file\" accept=\"image/*\" style=\"display:none\" onchange=\"gyxMemeUp(this)\"></label></div>\n        <input class=\"gyx-in\" placeholder=\"上面的字（可空）\" value=\"${X.esc(ST.top)}\" oninput=\"gyxMemeSet('top',this.value)\"><input class=\"gyx-in\" style=\"margin-top:6px\" placeholder=\"下面的字\" value=\"${X.esc(ST.bottom)}\" oninput=\"gyxMemeSet('bottom',this.value)\">\n        <div class=\"mm-phr\">${PHR.map(p => `<span class=\"gyx-chip\" onclick=\"this.closest('.mm-ctl').querySelectorAll('input.gyx-in')[1].value='${p}';gyxMemeSet('bottom','${p}')\">${p}</span>`).join('')}</div>\n        <div class=\"gyx-row\">字 <input type=\"range\" min=\"18\" max=\"72\" value=\"${ST.size}\" oninput=\"gyxMemeSet('size',+this.value)\" style=\"flex:1\"><input type=\"color\" value=\"${ST.color}\" onchange=\"gyxMemeSet('color',this.value)\" title=\"字的颜色\"><input type=\"color\" value=\"${ST.stroke}\" onchange=\"gyxMemeSet('stroke',this.value)\" title=\"描边\"><input type=\"color\" value=\"${ST.bg}\" onchange=\"gyxMemeSet('bg',this.value)\" title=\"底色\"></div>\n        <div class=\"gyx-row\">${[['sans', '圆体'], ['bold', '粗黑'], ['hand', '手写']].map(([k, n]) => `<span class=\"gyx-chip${ST.font === k ? ' on' : ''}\" onclick=\"gyxMemeSet('font','${k}');this.parentNode.querySelectorAll('.gyx-chip').forEach(e=>e.classList.remove('on'));this.classList.add('on')\">${n}</span>`).join('')}${[['sq', '方'], ['wide', '扁']].map(([k, n]) => `<span class=\"gyx-chip\" onclick=\"gyxMemeSet('shape','${k}')\">${n}</span>`).join('')}</div>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxMemeSave('${cid}')\">存进表情包库</button><button class=\"gyx-btn lite\" onclick=\"gyxMemeSave('${cid}',1)\">存好直接发</button></div></div></div>`);\n    paint();\n};\nX.ctx(id => { const L = D.list.filter(x => x.cid === String(id) && x.by === 'me').slice(0, 4); return L.length ? `【她用你的照片做过表情包】配字：${L.map(x => '「' + x.text + '」').join('')}。` : ''; }, 'gyxMeme');\nX.action({ key: 'gyx_meme', label: '用自己的照片做一张表情包发给她', hint: '斗图', need: c => !!imgOf(c) && !D.list.some(x => x.cid === String(c.id) && x.by === 'ta' && Date.now() - x.at < 2 * 864e5),\n    run: async c => { const it = await taMake(c, '想逗逗她'); sendMsg(c, it, 'ta'); return '做了张表情包：' + it.text; } }, 'gyxMeme');\nX.today(() => ({ title: '🎨 表情包', rows: D.list.filter(x => X.day(new Date(x.at)) === X.day()).slice(0, 4).map(x => ({ t: x.by === 'ta' ? 'TA 做的' : '我做的', x: X.esc(x.text), go: `gyxMemeOpen('${x.cid}','mine')` })) }), 'gyxMeme');\nX.widget('gyxMemeW', { n: '表情包工坊', sizes: ['s', 'm'], tap: () => window.gyxMemeOpen(), r: w => { const x = D.list[0]; if (!x) return X.gw(w, '🎨', '表情包工坊', ['做一张？']); return `<div class=\"gw-x ${w.size === 's' ? 's' : 'm'}\" style=\"background:#fff url(${x.src}) center/contain no-repeat;border-radius:inherit\"></div>`; } }, 'gyxMeme');\nX.memArr({ k: 'gyxMeme', ico: '🎨', n: '表情包工坊', d: '做过的表情包（改的是配字的记录，图不变）', arr: () => D.list, field: 'text', text: x => x.text, meta: x => (x.by === 'ta' ? 'TA 做的' : '我做的') + ' · ' + new Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxMeme');\nX.css('gyxMmCss', `.mm-wrap{display:flex;gap:14px;flex-wrap:wrap}.mm-prev{width:200px;height:200px;object-fit:contain;border-radius:14px;background:repeating-conic-gradient(#f3f3f3 0 25%,#fff 0 50%) 0 0/16px 16px;flex:none;margin:0 auto}.mm-ctl{flex:1;min-width:220px}.mm-src{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}.mm-src img{width:46px;height:46px;object-fit:cover;border-radius:10px;cursor:pointer;border:2px solid transparent}.mm-src img.on{border-color:#ff7aa2}.mm-up{width:46px;height:46px;border-radius:10px;border:2px dashed #ccc;display:flex;align-items:center;justify-content:center;color:#aaa;cursor:pointer;font-size:20px}.mm-phr{max-height:74px;overflow:auto;margin:6px 0}.mm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:8px}.mm-grid>div{text-align:center}.mm-grid img{width:100%;border-radius:12px;background:#f7f7f7}.mm-grid em{display:block;font-style:normal;font-size:11px;color:#999}.mm-grid span a{font-size:12px;margin:0 4px;cursor:pointer;color:#1d9bf0}`);\nX.mini({ id: 'gyxMeme', icon: '🎨', title: '表情包工坊', desc: '用 TA 的照片做表情包', cat: '一起做', onOpen: () => window.gyxMemeOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.list = D.list || []; })();\n\n//# sourceURL=gyx-plugin/表情包工坊.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎨 表情包工坊 出错：', e); }
/* ==== 📸 和TA合照 ==== */
try { new Function('X', 'applyMacros', "/* 📸 和TA合照：打开前置摄像头，TA 的立绘（桌面上的TA 里传的那几张，或者 TA 的头像）站在你旁边，拖一拖、调大小、倒数三秒——咔嚓。照片存进图库，TA 会看着照片说一句。没有摄像头就选一张你的照片来合 */\nif (window.__gyxDuo) return; window.__gyxDuo = 1;\nX.feat('gyxDuo', { n: '📸 和TA合照', desc: '前置摄像头 + TA 的立绘，倒数三秒拍合照，存进图库' });\nconst S = X.store('duo');\nlet D = { pics: [] };   // [{id, cid, src, at, say, gal}]  src 是压缩过的 jpeg\nlet CAM = null, ST = { x: .62, y: .28, s: .55, flip: false, frame: 0, img: '' };\nconst FRAMES = ['无', '拍立得', '日期', '爱心'];\nfunction stop() { try { if (CAM) CAM.getTracks().forEach(t => t.stop()); } catch (e) {} CAM = null; }\nconst taImg = c => { try { return (window.gyxPetImgOf && window.gyxPetImgOf(c)) || c.avatarImg || ''; } catch (e) { return c.avatarImg || ''; } };\nasync function cam() { stop(); try { CAM = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1080 }, height: { ideal: 1440 } }, audio: false }); const v = document.getElementById('gyxDuoV'); if (v) { v.srcObject = CAM; v.play().catch(() => {}); } return true; } catch (e) { const t = document.getElementById('gyxDuoTip'); if (t) t.textContent = '打不开前置摄像头（' + (e.name || '') + '），可以选一张你的照片来合。'; return false; } }\nfunction place() { const t = document.getElementById('gyxDuoTa'); if (!t) return; Object.assign(t.style, { left: (ST.x * 100) + '%', top: (ST.y * 100) + '%', width: (ST.s * 100) + '%', transform: `translate(-50%,0) scaleX(${ST.flip ? -1 : 1})` }); }\nwindow.gyxDuoSet = (k, v) => { if (k === 'flip') v = !ST.flip; ST[k] = v; place(); if (k === 'frame') document.querySelectorAll('.duo-fr span').forEach((e, i) => e.classList.toggle('on', i === v)); };\nfunction drag(e) { const box = document.getElementById('gyxDuoBox'), r = box.getBoundingClientRect(), p = e.touches ? e.touches[0] : e; ST.x = Math.max(0, Math.min(1, (p.clientX - r.left) / r.width)); ST.y = Math.max(-.3, Math.min(.95, (p.clientY - r.top) / r.height - ST.s * .35)); place(); }\nwindow.gyxDuoGrab = e => { e.preventDefault(); const mv = ev => drag(ev), up = () => { removeEventListener('mousemove', mv); removeEventListener('touchmove', mv); removeEventListener('mouseup', up); removeEventListener('touchend', up); }; addEventListener('mousemove', mv); addEventListener('touchmove', mv, { passive: false }); addEventListener('mouseup', up); addEventListener('touchend', up); };\nwindow.gyxDuoPick = inp => { const f = inp.files && inp.files[0]; if (!f) return; const fr = new FileReader(); fr.onload = () => { stop(); const b = document.getElementById('gyxDuoBg'); b.src = fr.result; b.style.display = 'block'; document.getElementById('gyxDuoV').style.display = 'none'; }; fr.readAsDataURL(f); };\nwindow.gyxDuoShot = async cid => {\n    const c = X.char(cid), cd = document.getElementById('gyxDuoCd');\n    for (const n of [3, 2, 1]) { cd.textContent = n; cd.style.display = 'flex'; await new Promise(r => setTimeout(r, 800)); } cd.style.display = 'none';\n    const box = document.getElementById('gyxDuoBox'), W = 900, H = Math.round(W * box.clientHeight / box.clientWidth), cv = document.createElement('canvas'); cv.width = W; cv.height = H; const g = cv.getContext('2d');\n    const v = document.getElementById('gyxDuoV'), bg = document.getElementById('gyxDuoBg'), src = bg.style.display === 'block' ? bg : v;\n    const sw = src.videoWidth || src.naturalWidth || W, sh = src.videoHeight || src.naturalHeight || H, k = Math.max(W / sw, H / sh);\n    g.save(); if (src === v) { g.translate(W, 0); g.scale(-1, 1); } g.drawImage(src, (W - sw * k) / 2, (H - sh * k) / 2, sw * k, sh * k); g.restore();\n    const ta = document.getElementById('gyxDuoTa'); if (ta && ta.complete && ta.naturalWidth) { const tw = ST.s * W, th = tw * ta.naturalHeight / ta.naturalWidth; g.save(); g.translate(ST.x * W, ST.y * H); if (ST.flip) g.scale(-1, 1); g.drawImage(ta, -tw / 2, 0, tw, th); g.restore(); }\n    let out = cv;\n    if (ST.frame === 1) { out = document.createElement('canvas'); out.width = W + 60; out.height = H + 200; const o = out.getContext('2d'); o.fillStyle = '#fff'; o.fillRect(0, 0, out.width, out.height); o.drawImage(cv, 30, 30); o.fillStyle = '#555'; o.font = '44px \"Ma Shan Zheng\",\"KaiTi\",cursive'; o.fillText(`和${X.name(c)} · ${X.day()}`, 40, H + 130); }\n    if (ST.frame === 2) { g.fillStyle = '#ff9a3c'; g.font = 'bold 40px monospace'; g.fillText(X.day().replace(/-/g, ' ').slice(2), W - 260, H - 40); }\n    if (ST.frame === 3) { g.font = '60px serif'; for (let i = 0; i < 9; i++) g.fillText('♥', (i * 137) % W, ((i * 211) % (H / 3)) + 50); }\n    let data; try { data = out.toDataURL('image/jpeg', .86); } catch (e) { X.toast('📸 拍不了', 'TA 的立绘是网络图片、浏览器不让合成。去「桌面上的TA」把立绘传成本地图片就行。'); return; }\n    try { const fl = document.getElementById('gyxDuoBox'); fl.classList.add('flash'); setTimeout(() => fl.classList.remove('flash'), 300); } catch (e) {}\n    let say = X.bailu() ? null : await X.ask(`${X.who(c)}\\n你们刚拍了一张合照（${['普通的', '拍立得相框的', '带日期的', '撒满爱心的'][ST.frame]}），现在 ${new Date().getHours()} 点。看着照片说一句（你看不清细节，就说你的感受，别描述画面）。`);\n    say = X.plain(say || X.pick(X.cards(['合照', '情话'], c, 1).concat([X.v('这张我要设成屏保。', '你笑得好好看，我站在旁边都不像我了。', '再拍一张！刚才我没准备好。', '洗出来吧，夹在钱包里。')])));\n    const it = { id: 'du' + Date.now().toString(36), cid: String(cid), src: data, at: Date.now(), say };\n    try { if (window.gyGallery) { const g2 = await window.gyGallery.add({ src: data, tag: '合照', by: 'me', note: `和${X.name(c)}：${say}` }); it.gal = g2 && g2.id; } } catch (e) {}\n    D.pics.unshift(it); await S.set('d', D);\n    X.panel('gyxDuoRes', '📸 咔嚓', `<img src=\"${data}\" style=\"width:100%;border-radius:14px\"><div class=\"gyx-card\">${X.esc(X.name(c))}：${X.esc(say)}</div><div class=\"gyx-row\"><a class=\"gyx-btn\" download=\"和${X.esc(X.name(c))}的合照-${X.day()}.jpg\" href=\"${data}\">保存到手机</a><button class=\"gyx-btn lite\" onclick=\"document.getElementById('gyxDuoRes').remove()\">再拍一张</button><button class=\"gyx-btn lite\" onclick=\"gyxDuoSend('${it.id}')\">发到聊天里</button></div>`);\n};\nwindow.gyxDuoSend = id => { const it = D.pics.find(x => x.id === id), c = it && X.char(it.cid); if (!c) return; try { const sid = String(c.id); globalChats[sid] = globalChats[sid] || []; globalChats[sid].push({ sender: 'me', text: `<img src=\"${it.src}\" style=\"max-width:220px;border-radius:10px\">`, timestamp: Date.now(), readBy: [], gyx: 1 }); saveAllData(); if (typeof renderChatMessages === 'function' && String(currentChatSessionId) === sid) renderChatMessages(); } catch (e) {} X.say(c, it.say); X.toast('📸 发过去了', ''); };\nwindow.gyxDuoDel = async id => { D.pics = D.pics.filter(x => x.id !== id); await S.set('d', D); window.gyxDuoAlbum(); };\nwindow.gyxDuoData = () => D;\nwindow.gyxDuoAlbum = () => X.panel('gyxDuoAl', '📸 我们的合照', `<div class=\"duo-al\">${D.pics.map(x => `<div><img src=\"${x.src}\" onclick=\"window.gyPhotoBig?gyPhotoBig(this.src):0\"><em>${X.esc(x.say)}</em><i onclick=\"gyxDuoDel('${x.id}')\">删</i></div>`).join('') || '<div class=\"gyx-tip\">还没合过照</div>'}</div>`);\nwindow.gyxDuoOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id); ST.img = taImg(c);\n    const ov = X.panel('gyxDuoOv', '📸 和 ' + X.esc(X.name(c)) + ' 合照', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxDuoOpen')}<span class=\"gyx-chip\" onclick=\"gyxDuoAlbum()\">相册（${D.pics.length}）</span></div>\n        <div id=\"gyxDuoBox\" class=\"duo-box\"><video id=\"gyxDuoV\" playsinline muted autoplay></video><img id=\"gyxDuoBg\" style=\"display:none\"><img id=\"gyxDuoTa\" src=\"${X.esc(ST.img)}\" onmousedown=\"gyxDuoGrab(event)\" ontouchstart=\"gyxDuoGrab(event)\" ${ST.img ? '' : 'style=\"display:none\"'}><div id=\"gyxDuoCd\" class=\"duo-cd\"></div></div>\n        <div id=\"gyxDuoTip\" class=\"gyx-tip\">${ST.img ? X.v('拖 TA 到你旁边。', 'TA 站好了，你也站好。', '把 TA 拖到你肩膀边上。') : 'TA 还没有立绘也没有头像——去「桌面上的TA」传几张立绘吧。'}</div>\n        <div class=\"gyx-row\">大小 <input type=\"range\" min=\"0.2\" max=\"1.2\" step=\"0.01\" value=\"${ST.s}\" oninput=\"gyxDuoSet('s',+this.value)\" style=\"flex:1\"><span class=\"gyx-chip\" onclick=\"gyxDuoSet('flip')\">↔ 翻转</span></div>\n        <div class=\"gyx-row duo-fr\">${FRAMES.map((f, i) => `<span class=\"gyx-chip${ST.frame === i ? ' on' : ''}\" onclick=\"gyxDuoSet('frame',${i})\">${f}</span>`).join('')}</div>\n        <div class=\"gyx-row\" style=\"justify-content:center\"><button class=\"gyx-btn\" onclick=\"gyxDuoShot('${cid}')\">📸 倒数拍</button><label class=\"gyx-btn lite\">选一张照片<input type=\"file\" accept=\"image/*\" style=\"display:none\" onchange=\"gyxDuoPick(this)\"></label></div>`);\n    const rm = ov.remove.bind(ov); ov.remove = () => { stop(); rm(); }; place(); cam();\n};\nX.ctx(id => { const x = D.pics.find(p => p.cid === String(id)); return x && Date.now() - x.at < 864e5 ? `【今天你们拍了合照】你当时说：「${x.say}」` : ''; }, 'gyxDuo');\nX.action({ key: 'gyx_duo', label: '想和她拍张合照', hint: '和TA合照', need: c => !!taImg(c) && !D.pics.some(x => x.cid === String(c.id) && Date.now() - x.at < 7 * 864e5),\n    run: async c => (await X.reach(c, '你很想和她拍一张合照（「📸 和TA合照」里你可以站在她旁边）。跟她说')) ? '想拍合照' : null }, 'gyxDuo');\nX.today(() => ({ title: '📸 合照', rows: D.pics.filter(x => X.day(new Date(x.at)) === X.day()).map(x => ({ t: '咔嚓', x: X.esc(x.say.slice(0, 26)), go: 'gyxDuoAlbum()' })) }), 'gyxDuo');\nX.widget('gyxDuoW', { n: '我们的合照', sizes: ['s', 'm'], tap: () => D.pics.length ? window.gyxDuoAlbum() : window.gyxDuoOpen(), r: w => { const x = D.pics[0]; if (!x) return X.gw(w, '📸', '和TA合照', ['拍一张？']); return `<div class=\"gw-x ${w.size === 's' ? 's' : 'm'}\" style=\"background:url(${x.src}) center/cover;border-radius:inherit;justify-content:flex-end;padding:6px\"><em style=\"color:#fff;text-shadow:0 1px 3px #000\">${X.esc(x.say.slice(0, 20))}</em></div>`; } }, 'gyxDuo');\nX.memArr({ k: 'gyxDuo', ico: '📸', n: '合照', d: '一起拍的合照和 TA 当时说的话', arr: () => D.pics, field: 'say', text: x => x.say, save: () => S.set('d', D) }, 'gyxDuo');\nX.css('gyxDuoCss', `.duo-box{position:relative;width:100%;aspect-ratio:3/4;background:#111;border-radius:18px;overflow:hidden;touch-action:none}.duo-box video,#gyxDuoBg{width:100%;height:100%;object-fit:cover;transform:scaleX(-1)}#gyxDuoBg{transform:none}#gyxDuoTa{position:absolute;cursor:grab;user-select:none;-webkit-user-drag:none;filter:drop-shadow(0 4px 10px rgba(0,0,0,.35))}.duo-cd{position:absolute;inset:0;display:none;align-items:center;justify-content:center;font-size:96px;color:#fff;text-shadow:0 2px 10px #000}.duo-box.flash::after{content:'';position:absolute;inset:0;background:#fff;animation:duof .3s}@keyframes duof{to{opacity:0}}.duo-al{display:grid;grid-template-columns:1fr 1fr;gap:8px}.duo-al div{position:relative}.duo-al img{width:100%;border-radius:12px;cursor:zoom-in}.duo-al em{font-style:normal;font-size:12px;color:#888;display:block}.duo-al i{position:absolute;top:6px;right:8px;font-style:normal;font-size:11px;color:#fff;background:rgba(0,0,0,.4);padding:1px 6px;border-radius:8px;cursor:pointer}`);\nX.mini({ id: 'gyxDuo', icon: '📸', title: '和TA合照', desc: 'TA 的立绘站在你旁边，倒数拍合照', cat: '一起做', onOpen: () => window.gyxDuoOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.pics = D.pics || []; })();\n\n//# sourceURL=gyx-plugin/和TA合照.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 📸 和TA合照 出错：', e); }
/* ==== 💑 情侣头像 ==== */
try { new Function('X', 'applyMacros', "/* 💑 情侣头像：给你和 TA 做一对情侣头像——两张放在一起能拼成一个画面（半颗心、一人一半的月亮、同一片海……）。有生图就用原来「角色发图」里配好的生图（会带上 TA 的形象词），没有就用内置的画风现画；一键换上，随时换回原来的 */\nif (window.__gyxAvatar) return; window.__gyxAvatar = 1;\nX.feat('gyxAvatar', { n: '💑 情侣头像', desc: '给你和 TA 做一对能拼在一起的情侣头像，一键换上' });\nconst S = X.store('avatar');\nlet D = { list: [], backup: {}, cfg: {} };   // list: {id, cid, me, ta, theme, style, by, at, used}; backup[cid] = {me, ta}\nconst THEMES = [['heart', '💗 半颗心', ['#ff9a9e', '#fecfef']], ['moon', '🌙 日月', ['#2b3a67', '#f6d365']], ['sea', '🌊 同一片海', ['#89f7fe', '#66a6ff']], ['cat', '🐱 两只猫', ['#fbc2eb', '#a6c1ee']], ['star', '✨ 星星连线', ['#1e1b4b', '#6366f1']], ['flower', '🌷 一束花', ['#d4fc79', '#96e6a1']], ['umbrella', '☂️ 同一把伞', ['#a1c4fd', '#c2e9fb']], ['bubble', '💬 对话框', ['#ffecd2', '#fcb69f']]];\nconst STYLES = ['日系插画', '线稿', '水彩', '像素', 'Q 版', '赛璐璐'];\nconst PIC = { heart: ['💗', '💗'], moon: ['☀️', '🌙'], sea: ['🐚', '🐟'], cat: ['🐈', '🐈‍⬛'], star: ['⭐', '🌟'], flower: ['🌷', '🌼'], umbrella: ['☂️', '🌧️'], bubble: ['💬', '💭'] };\n// 内置画法：同一张渐变底，各拿一半图案，两张并排刚好拼起来\nfunction draw(theme, half, label) {\n    const th = THEMES.find(t => t[0] === theme) || THEMES[0], [a, b] = th[2], cv = document.createElement('canvas'); cv.width = cv.height = 512; const g = cv.getContext('2d');\n    const gr = g.createLinearGradient(half === 'l' ? 0 : -512, 0, half === 'l' ? 1024 : 512, 512); gr.addColorStop(0, a); gr.addColorStop(1, b); g.fillStyle = gr; g.fillRect(0, 0, 512, 512);\n    g.save(); g.translate(half === 'l' ? 512 : 0, 256);\n    if (theme === 'heart') { g.fillStyle = 'rgba(255,255,255,.85)'; g.beginPath(); g.moveTo(0, 150); g.bezierCurveTo(-260, -20, -150, -230, 0, -110); g.bezierCurveTo(150, -230, 260, -20, 0, 150); g.fill(); }\n    else { g.font = '300px serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(PIC[theme][half === 'l' ? 0 : 1], half === 'l' ? -240 : 240, 0); }\n    g.restore();\n    for (let i = 0; i < 18; i++) { g.fillStyle = 'rgba(255,255,255,' + (0.2 + Math.random() * 0.5) + ')'; g.beginPath(); g.arc(Math.random() * 512, Math.random() * 512, 2 + Math.random() * 5, 0, 7); g.fill(); }\n    if (label) { g.fillStyle = 'rgba(255,255,255,.92)'; g.font = 'bold 44px sans-serif'; g.textAlign = 'center'; g.fillText(label.slice(0, 6), 256, 470); }\n    return cv.toDataURL('image/png');\n}\nasync function gen(c, theme, style, by) {\n    const th = THEMES.find(t => t[0] === theme) || THEMES[0];\n    let me = '', ta = '';\n    const canGen = !X.bailu() && window.gyPhotoGet && useGen();\n    if (canGen) {\n        const look = (window.gyPhotoLookOf && window.gyPhotoLookOf(c.id)) || '';\n        const base = `情侣头像，${style}风格，主题「${th[1].replace(/^\\S+\\s/, '')}」，两张放在一起左右能拼成一个完整的画面，构图对称，头像用的正方形`;\n        try { const a = await window.gyPhotoGet(c.id, base + '，左边这张：女生', false, 'gen'); me = a && a.src || ''; } catch (e) {}\n        try { const b = await window.gyPhotoGet(c.id, base + '，右边这张' + (look ? '：' + look : ''), true, 'gen'); ta = b && b.src || ''; } catch (e) {}\n    }\n    if (!me || !ta) { me = draw(theme, 'l', ''); ta = draw(theme, 'r', ''); }\n    const it = { id: 'av' + Date.now(), cid: String(c.id), me, ta, theme, style, by: by || 'me', at: Date.now(), used: false };\n    D.list.unshift(it); D.list = D.list.slice(0, 30); await S.set('d', D); return it;\n}\nwindow.gyxAvatarGen = async function (cid, theme, style) {\n    const c = X.char(cid || window.GYX_AV_WHO) || X.cur(); if (!c) return null;\n    const b = document.getElementById('gyxAvGo'); if (b) { b.disabled = true; b.textContent = X.v('在画……', '画好马上给你看'); }\n    const it = await gen(c, theme || window.GYX_AV_TH || 'heart', style || window.GYX_AV_ST || STYLES[0], 'me');\n    window.gyxAvatarOpen(c.id); return it;\n};\nwindow.gyxAvatarUse = async function (id) {\n    const it = D.list.find(x => x.id === id); if (!it) return; const c = X.char(it.cid); if (!c) return;\n    if (!D.backup[it.cid]) D.backup[it.cid] = { me: (typeof currentUser !== 'undefined' && currentUser.avatarImg) || '', ta: c.avatarImg || '' };\n    try { if (typeof currentUser !== 'undefined') currentUser.avatarImg = it.me; c.avatarImg = it.ta; if (typeof saveAllData === 'function') saveAllData(); } catch (e) {}\n    D.list.forEach(x => x.used = x.id === id); await S.set('d', D);\n    X.toast(X.v('换好啦', '情侣头像换上了', '现在是一对了'), X.v('聊天里看看', '去看看'));\n    X.reach(c, '她刚刚把你们俩的头像换成了一对情侣头像，说说你看到时的反应');\n    try { if (typeof renderChatMessages === 'function') renderChatMessages(); } catch (e) {} X.repaint(); window.gyxAvatarOpen(it.cid);\n};\nwindow.gyxAvatarBack = async function (cid) {\n    const b = D.backup[cid], c = X.char(cid); if (!b || !c) return;\n    try { if (typeof currentUser !== 'undefined') currentUser.avatarImg = b.me; c.avatarImg = b.ta; if (typeof saveAllData === 'function') saveAllData(); } catch (e) {}\n    delete D.backup[cid]; D.list.forEach(x => { if (x.cid === cid) x.used = false; }); await S.set('d', D); X.toast(X.v('换回原来的了', '恢复好了')); window.gyxAvatarOpen(cid);\n};\nwindow.GYX_AV_WHO = ''; window.GYX_AV_TH = 'heart'; window.GYX_AV_ST = STYLES[0];\nwindow.gyxAvatarWho = v => { window.gyxAvatarOpen(v); };\nwindow.gyxAvatarOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id); window.GYX_AV_WHO = cid;\n    const L = D.list.filter(x => x.cid === cid);\n    X.panel('gyxAvOv', '💑 情侣头像', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxAvatarWho')}</div>\n        <div class=\"gyx-tip\">选个主题</div><div class=\"gyx-row\">${THEMES.map(t => `<span class=\"gyx-chip ${window.GYX_AV_TH === t[0] ? 'on' : ''}\" onclick=\"GYX_AV_TH='${t[0]}';gyxAvatarOpen('${cid}')\">${t[1]}</span>`).join('')}</div>\n        <div class=\"gyx-tip\">画风（有生图时才用得上）</div><div class=\"gyx-row\">${STYLES.map(s => `<span class=\"gyx-chip ${window.GYX_AV_ST === s ? 'on' : ''}\" onclick=\"GYX_AV_ST='${s}';gyxAvatarOpen('${cid}')\">${s}</span>`).join('')}</div>\n        ${X.bailu() ? '' : `<label class=\"gyx-row gyx-tip\"><input type=\"checkbox\" ${useGen() ? 'checked' : ''} onchange=\"gyxAvatarCfg(this.checked)\"> 用生图画（走「角色发图」里配的画图接口，没配就用免费那档；不勾＝用内置画法，马上出来）</label>`}\n        <div class=\"gyx-row\"><button id=\"gyxAvGo\" class=\"gyx-btn\" onclick=\"gyxAvatarGen('${cid}')\">做一对</button>${D.backup[cid] ? `<button class=\"gyx-btn lite\" onclick=\"gyxAvatarBack('${cid}')\">换回原来的头像</button>` : ''}</div>\n        <div class=\"av-list\">${L.map(x => `<div class=\"av-pair${x.used ? ' used' : ''}\"><div class=\"av-two\"><img src=\"${x.me}\"><img src=\"${x.ta}\"></div><div class=\"gyx-row\"><span class=\"gyx-tip\">${x.by === 'me' ? '你做的' : X.esc(X.name(c)) + ' 挑的'} · ${new Date(x.at).toLocaleDateString()}</span>${x.used ? '<b class=\"av-on\">正在用</b>' : `<button class=\"gyx-btn lite\" onclick=\"gyxAvatarUse('${x.id}')\">换上</button>`}</div></div>`).join('') || '<div class=\"gyx-tip\">还没做过。左边是你，右边是 TA，放在一起是一个画面。</div>'}</div>`);\n};\nwindow.gyxAvatarData = () => D;\nfunction useGen() { if (D.cfg.gen != null) return D.cfg.gen; try { return window.gyPhotoCfg && window.gyPhotoCfg().mode === 'gen'; } catch (e) { return false; } }\nwindow.gyxAvatarCfg = v => { D.cfg.gen = v; S.set('d', D); };\nX.action({ key: 'gyx_avatar', label: '想和她换一对情侣头像，挑一对给她看', hint: '想让别人一看就知道你们是一对', need: c => !D.list.some(x => x.cid === String(c.id) && Date.now() - x.at < 7 * 86400000), run: async c => { const it = await gen(c, X.pick(THEMES)[0], X.pick(STYLES), String(c.id)); return (await X.reach(c, `你挑了一对情侣头像（主题：${(THEMES.find(t => t[0] === it.theme) || THEMES[0])[1]}）想和她换上，问问她喜不喜欢（在「情侣头像」里能看到、能一键换上）`)) ? '挑了一对情侣头像给你' : null; } }, 'gyxAvatar');\nX.ctx(id => { const u = D.list.find(x => x.cid === String(id) && x.used); return u ? '【情侣头像】你们现在用的是一对情侣头像。' : ''; }, 'gyxAvatar');\nX.today(() => ({ title: '💑 情侣头像', rows: D.list.filter(x => x.by !== 'me' && !x.used && Date.now() - x.at < 3 * 86400000).map(x => ({ t: '新的', x: `${X.esc(X.name(X.char(x.cid)))} 挑了一对情侣头像给你`, go: `gyxAvatarOpen('${x.cid}')` })) }), 'gyxAvatar');\nX.widget('gyxAvatarW', { n: '情侣头像', sizes: ['s', 'm'], tap: () => window.gyxAvatarOpen(), r: w => { const x = D.list.find(i => i.used) || D.list[0]; if (!x) return X.gw(w, '💑', '情侣头像', ['做一对']); return `<div class=\"av-w\"><img src=\"${x.me}\"><img src=\"${x.ta}\"></div>`; } }, 'gyxAvatar');\nX.css('gyxAvCss', `.av-list{display:flex;flex-direction:column;gap:12px;margin-top:10px}.av-pair{padding:10px;border-radius:18px;background:#fafafa}.av-pair.used{background:#fff0f5}.av-two{display:flex;justify-content:center}.av-two img{width:42%;aspect-ratio:1;object-fit:cover;border-radius:50%;border:3px solid #fff;box-shadow:0 4px 12px rgba(0,0,0,.1)}.av-two img+img{margin-left:-4%}.av-on{color:#ff5c8a;font-size:13px;margin-left:auto}\n.av-w{height:100%;display:flex;align-items:center;justify-content:center}.av-w img{height:80%;aspect-ratio:1;border-radius:50%;object-fit:cover;border:2px solid #fff}.av-w img+img{margin-left:-10%}`);\nX.mini({ id: 'gyxAvatar', icon: '💑', title: '情侣头像', desc: '做一对能拼在一起的情侣头像，一键换上，随时换回', onOpen: () => window.gyxAvatarOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.list = D.list || []; D.backup = D.backup || {}; })();\n\n//# sourceURL=gyx-plugin/情侣头像.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 💑 情侣头像 出错：', e); }
